/** Body of a request that changes part of a book: only the fields sent change. */
public class BookUpdate extends Payload {

    @Size(min = 1, max = 200)
    private String title;

    @Pattern(regexp = "^[0-9]{13}$")
    private String isbn;

    private UUID authorId;

    private Genre genre;

