package com.example.api.repository;

import java.util.Optional;
import java.util.UUID;

import com.example.api.common.ListQuery;
import com.example.api.common.ListResult;
import com.example.api.model.Author;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.Sort;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.stereotype.Repository;

/** Keeps authors in the database with JPA. */
@Repository
public class JpaAuthorRepository implements AuthorRepository {

    private final AuthorJpaRepository data;

    public JpaAuthorRepository(AuthorJpaRepository data) {
        this.data = data;
    }

    /** The Java property of a JSON field name. */
    private static String property(String field) {
        return switch (field) {
            case "id" -> "id";
            case "name" -> "name";
            case "email" -> "email";
            case "born" -> "born";
            default -> field;
        };
    }

    @Override
    public ListResult<Author> list(ListQuery query) {
        Specification<Author> filters = (root, criteria, builder) -> builder.and(query.filters().entrySet().stream()
                .map(filter -> builder.equal(root.get(property(filter.getKey())), filter.getValue()))
                .toArray(jakarta.persistence.criteria.Predicate[]::new));
        Sort sort = query.sortField() == null ? Sort.by("id")
                : Sort.by(query.descending() ? Sort.Direction.DESC : Sort.Direction.ASC, property(query.sortField())).and(Sort.by("id"));
        if (query.limit() == null) {
            var items = data.findAll(filters, sort);
            return new ListResult<>(items, items.size());
        }
        // Offsets are always whole pages of `limit` items
        Pageable page = PageRequest.of(query.offset() / query.limit(), query.limit(), sort);
        Page<Author> found = data.findAll(filters, page);
        return new ListResult<>(found.getContent(), found.getTotalElements());
    }

    @Override
    public Optional<Author> get(UUID key) {
        return data.findById(key);
    }

    @Override
    public Author add(Author item) {
        return data.saveAndFlush(item);
    }

    @Override
    public Author update(Author item) {
        return data.saveAndFlush(item);
    }

    @Override
    public void delete(UUID key) {
        data.deleteById(key);
        data.flush();
    }
}

